<!-- components/marketplace/ProductExcelExport.vue -->
<template>
  <button @click="exportExcel" class="excel-export-btn" :disabled="loading">
    <i class="fa fa-spinner fa-pulse mr-2" v-if="loading"></i>
    <i class="fa fa-file-excel mr-2" v-else></i>
    {{ loading ? 'Generando Excel...' : 'Exportar a Excel' }}
  </button>
</template>

<script>
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import moment from 'moment';

export default {
  name: "ProductExcelExport",
  props: {
    productData: {
      type: Array, // Array de productos (ahora se usa como fallback)
      required: true
    },
    filters: {
      type: Object,
      default: () => ({})
    },
    filename: {
      type: String,
      default: "productos-marketplace.xlsx"
    },
    exportFunction: {
      type: Function, // Función asíncrona para obtener todos los datos
      default: null
    }
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    totalProducts() {
      return this.productData?.length || 0;
    },
    totalStock() {
      return this.productData?.reduce((sum, product) => sum + (parseInt(product.stock) || 0), 0) || 0;
    },
    totalValue() {
      return this.productData?.reduce((sum, product) => sum + (parseFloat(product.sale) || 0) * (parseInt(product.stock) || 0), 0) || 0;
    },
    totalCost() {
      return this.productData?.reduce((sum, product) => sum + (parseFloat(product.cost) || 0) * (parseInt(product.stock) || 0), 0) || 0;
    },
    activeProducts() {
      return this.productData?.filter(product => product.active).length || 0;
    },
    offerProducts() {
      return this.productData?.filter(product => product.in_offer).length || 0;
    },
    deliveryFreeProducts() {
      return this.productData?.filter(product => product.delivery_free).length || 0;
    },
    outOfStockProducts() {
      return this.productData?.filter(product => !product.stock || product.stock === 0).length || 0;
    }
  },
  methods: {
    async exportExcel() {
      try {
        this.loading = true;
        
        // Obtener datos: usar la función de exportación si existe, si no usar productData
        let dataToExport = this.productData;
        if (this.exportFunction && typeof this.exportFunction === 'function') {
          dataToExport = await this.exportFunction();
        }
        
        // Validar que tengamos datos
        if (!dataToExport || !Array.isArray(dataToExport)) {
          throw new Error('No se pudieron obtener los datos para exportar');
        }
        
        // Crear workbook
        const wb = XLSX.utils.book_new();
        
        // Hoja de productos principal
        const productsSheet = this.createProductsSheet(dataToExport);
        XLSX.utils.book_append_sheet(wb, productsSheet, "Productos");
        
        // Hoja de resumen
        const summarySheet = this.createSummarySheet(dataToExport);
        XLSX.utils.book_append_sheet(wb, summarySheet, "Resumen");
        
        // Hoja de filtros aplicados
        const filtersSheet = this.createFiltersSheet(dataToExport);
        XLSX.utils.book_append_sheet(wb, filtersSheet, "Filtros Aplicados");
        
        // Generar archivo
        const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const data = new Blob([excelBuffer], { type: 'application/octet-stream' });
        saveAs(data, this.filename);
        
      } catch (error) {
        console.error("Error exportando Excel:", error);
        alert("Error al generar el archivo Excel: " + error.message);
      } finally {
        this.loading = false;
      }
    },

    createProductsSheet(productData = this.productData) {
      const data = [
        ['LISTADO DE PRODUCTOS MARKETPLACE'],
        [],
        ['ID', 'Nombre', 'Precio Venta', 'Costo', 'Stock', 'Valor Total', 'En Oferta', 'Delivery Gratis', 'Activo', 'Categoría', 'Fecha Creación']
      ];
      
      productData.forEach(product => {
        const totalValue = (parseFloat(product.sale) || 0) * (parseInt(product.stock) || 0);
        
        data.push([
          product.id || '',
          product.alias || '',
          `$${(parseFloat(product.sale) || 0).toFixed(2)}`,
          `$${(parseFloat(product.cost) || 0).toFixed(2)}`,
          product.stock || 0,
          `$${totalValue.toFixed(2)}`,
          product.in_offer ? 'Sí' : 'No',
          product.delivery_free ? 'Sí' : 'No',
          product.active ? 'Sí' : 'No',
          product.category || '',
          product.created_at ? this.formatDate(product.created_at) : ''
        ]);
      });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 10 }, // ID
        { wch: 40 }, // Nombre
        { wch: 15 }, // Precio Venta
        { wch: 15 }, // Costo
        { wch: 10 }, // Stock
        { wch: 15 }, // Valor Total
        { wch: 12 }, // En Oferta
        { wch: 15 }, // Delivery Gratis
        { wch: 10 }, // Activo
        { wch: 20 }, // Categoría
        { wch: 20 }  // Fecha Creación
      ];
      
      return ws;
    },

    createSummarySheet(productData = this.productData) {
      const totalProducts = productData?.length || 0;
      const totalStock = productData?.reduce((sum, product) => sum + (parseInt(product.stock) || 0), 0) || 0;
      const totalValue = productData?.reduce((sum, product) => sum + (parseFloat(product.sale) || 0) * (parseInt(product.stock) || 0), 0) || 0;
      const totalCost = productData?.reduce((sum, product) => sum + (parseFloat(product.cost) || 0) * (parseInt(product.stock) || 0), 0) || 0;
      const activeProducts = productData?.filter(product => product.active).length || 0;
      const offerProducts = productData?.filter(product => product.in_offer).length || 0;
      const deliveryFreeProducts = productData?.filter(product => product.delivery_free).length || 0;
      const outOfStockProducts = productData?.filter(product => !product.stock || product.stock === 0).length || 0;
      
      const data = [
        ['RESUMEN DE PRODUCTOS MARKETPLACE'],
        [],
        ['Estadísticas Generales', ''],
        ['Total Productos', totalProducts],
        ['Productos Activos', activeProducts],
        ['Productos Inactivos', totalProducts - activeProducts],
        ['Productos en Oferta', offerProducts],
        ['Delivery Gratis', deliveryFreeProducts],
        ['Sin Stock', outOfStockProducts],
        [],
        ['Valores Totales', ''],
        ['Stock Total Unidades', totalStock],
        ['Valor Total Inventario', `$${totalValue.toFixed(2)}`],
        ['Costo Total Inventario', `$${totalCost.toFixed(2)}`],
        ['Utilidad Potencial', `$${(totalValue - totalCost).toFixed(2)}`],
        ['Margen Promedio', `${totalValue > 0 ? ((totalValue - totalCost) / totalValue * 100).toFixed(1) : 0}%`],
        [],
        ['Distribución', ''],
        ['% Productos Activos', `${totalProducts > 0 ? (activeProducts / totalProducts * 100).toFixed(1) : 0}%`],
        ['% Productos en Oferta', `${totalProducts > 0 ? (offerProducts / totalProducts * 100).toFixed(1) : 0}%`],
        ['% Delivery Gratis', `${totalProducts > 0 ? (deliveryFreeProducts / totalProducts * 100).toFixed(1) : 0}%`],
        ['% Sin Stock', `${totalProducts > 0 ? (outOfStockProducts / totalProducts * 100).toFixed(1) : 0}%`],
        [],
        ['Fecha de generación', new Date().toLocaleString('es-ES')]
      ];
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 30 },
        { wch: 20 }
      ];
      
      return ws;
    },

    createFiltersSheet(productData = this.productData) {
      const totalProducts = productData?.length || 0;
      const data = [
        ['FILTROS APLICADOS'],
        [],
        ['Filtro', 'Valor']
      ];
      
      if (this.filters.name) data.push(['Nombre Producto', this.filters.name]);
      if (this.filters.min_price) data.push(['Precio Mínimo', `$${this.filters.min_price}`]);
      if (this.filters.max_price) data.push(['Precio Máximo', `$${this.filters.max_price}`]);
      if (this.filters.min_cost) data.push(['Costo Mínimo', `$${this.filters.min_cost}`]);
      if (this.filters.max_cost) data.push(['Costo Máximo', `$${this.filters.max_cost}`]);
      if (this.filters.min_stock) data.push(['Stock Mínimo', this.filters.min_stock]);
      if (this.filters.max_stock) data.push(['Stock Máximo', this.filters.max_stock]);
      if (this.filters.active) data.push(['Activo', 'Sí']);
      if (this.filters.in_offer) data.push(['En Oferta', 'Sí']);
      if (this.filters.delivery_free) data.push(['Delivery Gratis', 'Sí']);
      
      data.push([]);
      data.push(['Resultados', '']);
      data.push(['Total Productos Encontrados', totalProducts]);
      data.push(['Fecha de exportación', new Date().toLocaleString('es-ES')]);
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 25 },
        { wch: 40 }
      ];
      
      return ws;
    },

    formatDate(date) {
      if (!date) return '';
      return moment(date).format('DD/MM/YYYY');
    }
  }
};
</script>

<style scoped>
.excel-export-btn {
  padding: 8px 16px;
  background-color: #016526;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
}
.excel-export-btn:hover:not(:disabled) {
  background-color: #008531;
  transform: translateY(-1px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.excel-export-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
</style>
