<template>
    <div class="crud-marketplace-product-export">
        <form action="" class="mt-2" @submit.prevent="searchProducts">
            <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
                <h2 class="inline text-darkGray text-xl ml-4 mb-3">Filtros de Productos</h2>
                
                <!-- Product Name Search -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
                        Nombre Producto
                    </label>
                    <input type="text" 
                        v-model="filters.name"
                        placeholder="Buscar por nombre..."
                        class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                </div>

                <!-- Price Range -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
                        Rango de Precio
                    </label>
                    <div class="flex-1 flex flex-row gap-2">
                        <input type="number" 
                            v-model="filters.min_price"
                            placeholder="Mínimo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                        <input type="number" 
                            v-model="filters.max_price"
                            placeholder="Máximo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </div>
                </div>

                <!-- Cost Range -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
                        Rango de Costo
                    </label>
                    <div class="flex-1 flex flex-row gap-2">
                        <input type="number" 
                            v-model="filters.min_cost"
                            placeholder="Mínimo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                        <input type="number" 
                            v-model="filters.max_cost"
                            placeholder="Máximo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </div>
                </div>

                <!-- Stock Range -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
                        Rango de Stock
                    </label>
                    <div class="flex-1 flex flex-row gap-2">
                        <input type="number" 
                            v-model="filters.min_stock"
                            placeholder="Mínimo"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                        <input type="number" 
                            v-model="filters.max_stock"
                            placeholder="Máximo"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </div>
                </div>

                <!-- Status Filters -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32">
                        Estado
                    </label>
                    <div class="flex-1 flex flex-row gap-4">
                        <label class="flex items-center">
                            <input type="checkbox" v-model="filters.active" class="mr-2">
                            <span class="text-sm">Activo</span>
                        </label>
                        <label class="flex items-center">
                            <input type="checkbox" v-model="filters.in_offer" class="mr-2">
                            <span class="text-sm">En Oferta</span>
                        </label>
                        <label class="flex items-center">
                            <input type="checkbox" v-model="filters.delivery_free" class="mr-2">
                            <span class="text-sm">Delivery Gratis</span>
                        </label>
                    </div>
                </div>

                <!-- Active Filters Summary -->
                <div class="flex flex-wrap gap-2 mt-4 mx-2" v-if="hasActiveFilters">
                    <span class="text-sm text-gray-600 mr-2">Filtros activos:</span>
                    <span v-for="(value, key) in activeFilters" :key="key" 
                        class="inline-flex items-center px-2 py-1 rounded-md text-xs font-medium bg-blue-100 text-blue-800">
                        {{ getFilterLabel(key) }}: {{ formatFilterValue(key, value) }}
                        <button @click="clearFilter(key)" class="ml-1 hover:text-blue-600">
                            <i class="fas fa-times"></i>
                        </button>
                    </span>
                    <button @click="clearAllFilters" class="text-xs text-red-600 hover:text-red-800 ml-2">
                        Limpiar todos
                    </button>
                </div>
            </div>   
                
            <!-- Buttons -->
            <div class="flex flex-1 gap-3 mt-10 gap-y-4">
                <div class="flex flex-col mr-auto">
                    <small class="text-darkGray">Use los filtros para refinar su búsqueda</small>
                    <transition name="fade">
                        <small class="bg-red text-white px-3 py-2 mt-3 rounded" v-if="show_error">
                            <i class="fa fa-info-circle"></i> {{ error_message }}
                        </small>
                    </transition>
                </div>                                   
                <button type="button" 
                    class="inline-flex border border-gray-400 h-10 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:bg-red-600 focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    disabled:opacity-25 transition items-center"
                    :disabled="isLoading"
                    @click="resetForm">
                    <i class="fas fa-times mr-2"></i>
                    Cancelar
                </button>         
                <button type="submit" 
                    class="inline-flex border border-transparent h-10 bg-green-600 rounded-md font-semibold text-xs text-white uppercase tracking-widest px-4 py-2 
                hover:bg-green-500 focus:outline-none focus:border-green-700 focus:ring focus:ring-green-200
                disabled:opacity-25 transition items-center"
                    :disabled="isLoading">
                    <span class="pr-2" v-if="isLoading">
                        <i class="fa fa-spinner fa-pulse"></i>
                    </span>
                    <i class="fas fa-search mr-2" v-else></i>
                    Buscar Productos
                </button>                              
            </div>
        </form>

        <!-- Results Section -->
        <div v-if="showResults" class="mt-8">
            <div class="border-t border-gray-200 my-4"></div>
            
            <!-- Mostrar spinner mientras carga -->
            <div v-if="isLoading" class="flex justify-center items-center py-12">
                <div class="text-center">
                    <i class="fas fa-spinner fa-pulse fa-3x text-blue-500 mb-3"></i>
                    <p class="text-gray-600">Buscando productos...</p>
                </div>
            </div>

            <!-- Mostrar error si ocurre -->
            <div v-else-if="searchError" class="bg-red-50 border-l-4 border-red-400 p-4 mb-4">
                <div class="flex">
                    <div class="flex-shrink-0">
                        <i class="fas fa-exclamation-circle text-red-400"></i>
                    </div>
                    <div class="ml-3">
                        <p class="text-sm text-red-700">{{ searchError }}</p>
                    </div>
                </div>
            </div>

            <!-- Mostrar mensaje si no hay datos -->
            <div v-else-if="productData && !hasData" class="bg-yellow-50 border-l-4 border-yellow-400 p-4">
                <div class="flex">
                    <div class="flex-shrink-0">
                        <i class="fas fa-exclamation-triangle text-yellow-400"></i>
                    </div>
                    <div class="ml-3">
                        <p class="text-sm text-yellow-700">
                            No se encontraron productos con los filtros seleccionados.
                        </p>
                    </div>
                </div>
            </div>

            <!-- Mostrar resultados y exportación -->
            <div v-else-if="productData && hasData" class="mt-4">
                <div class="bg-green-50 border-l-4 border-green-400 p-4 mb-4">
                    <div class="flex">
                        <div class="flex-shrink-0">
                            <i class="fas fa-check-circle text-green-400"></i>
                        </div>
                        <div class="ml-3">
                            <p class="text-sm text-green-700">
                                Se encontraron {{ totalCount }} productos. Puede exportarlos a Excel.
                            </p>
                        </div>
                    </div>
                </div>

                <!-- Export Button -->
                <div class="flex justify-end mb-4">
                    <ProductExcelExport 
                        :productData="[]"
                        :filters="filters"
                        :filename="getExportFilename()"
                        :export-function="exportExcel"
                    />
                </div>

                <!-- Preview Table -->
                <div class="overflow-x-auto">
                    <table class="min-w-full bg-white border border-gray-300">
                        <thead class="bg-gray-50">
                            <tr>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Nombre
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Precio
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Costo
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Stock
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    En Oferta
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Delivery Gratis
                                </th>
                                <th class="px-6 py-3 border-b border-gray-200 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Activo
                                </th>
                            </tr>
                        </thead>
                        <tbody class="bg-white divide-y divide-gray-200">
                            <tr v-for="product in paginatedProductData" :key="product.id">
                                <td class="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                    {{ product.alias }}
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    ${{ parseFloat(product.sale || 0).toFixed(2) }}
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    ${{ parseFloat(product.cost || 0).toFixed(2) }}
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    {{ product.stock || 0 }}
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span :class="product.in_offer ? 'text-green-600' : 'text-red-600'">
                                        {{ product.in_offer ? 'Sí' : 'No' }}
                                    </span>
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span :class="product.delivery_free ? 'text-green-600' : 'text-red-600'">
                                        {{ product.delivery_free ? 'Sí' : 'No' }}
                                    </span>
                                </td>
                                <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span :class="product.active ? 'text-green-600' : 'text-red-600'">
                                        {{ product.active ? 'Sí' : 'No' }}
                                    </span>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>

                <!-- Pagination Component -->
                <div v-if="totalCount >= 0" class="mt-6">
                    <CustomPagination 
                        :current-page="currentPage"
                        :total-pages="totalPages"
                        :total-count="totalCount"
                        :page-size="pageSize"
                        @page-changed="onPageChanged"
                        @page-size-changed="onPageSizeChanged"
                    />
                </div>                
            </div>
        </div>
    </div>
</template>

<script>
import moment from 'moment'
import Swal from 'sweetalert2';
import ProductExcelExport from '@/components/marketplace/ProductExcelExport.vue';
import CustomPagination from '@/components/Admin/CustomPagination.vue';

// Services
import MarketplaceItemService from '@/services/marketplace/marketplace_item.service';

export default {
    name: "CrudMarketplaceProductExport",
    components: {
        ProductExcelExport,
        CustomPagination
    },
    data() {
        return {
            // Loading states
            isLoading: false,
            show_error: false,
            error_message: 'Error en la búsqueda',
            
            // Form filters
            filters: {
                name: '',
                min_price: null,
                max_price: null,
                min_cost: null,
                max_cost: null,
                min_stock: null,
                max_stock: null,
                active: false,
                in_offer: false,
                delivery_free: false
            },
            
            // Pagination
            currentPage: 1,
            pageSize: 10,
            totalCount: 0,
            totalPages: 0,
            
            // Results
            showResults: false,
            productData: null,
            searchError: null
        }
    },
    computed: {
        // Check if there are active filters
        hasActiveFilters() {
            return Object.keys(this.activeFilters).length > 0;
        },
        
        // Get only active filters (with values)
        activeFilters() {
            const active = {};
            Object.entries(this.filters).forEach(([key, value]) => {
                if (value !== null && value !== '' && value !== undefined && value !== false) {
                    active[key] = value;
                }
            });
            return active;
        },

        // Verificar si hay datos para mostrar
        hasData() {
            return this.productData && this.productData.length > 0;
        },

        // Calcular items para mostrar en la página actual
        paginatedProductData() {
            if (!this.productData) return [];
            // Los datos que recibimos del backend ya están paginados
            // gracias a los parámetros limit y offset
            return this.productData;
        }
    },
    methods: {
        // Get label for filter (for display)
        getFilterLabel(key) {
            const labels = {
                name: 'Nombre',
                min_price: 'Precio mín',
                max_price: 'Precio máx',
                min_cost: 'Costo mín',
                max_cost: 'Costo máx',
                min_stock: 'Stock mín',
                max_stock: 'Stock máx',
                active: 'Activo',
                in_offer: 'En oferta',
                delivery_free: 'Delivery gratis'
            };
            return labels[key] || key;
        },
        
        // Format filter value for display
        formatFilterValue(key, value) {
            if (key === 'active' || key === 'in_offer' || key === 'delivery_free') {
                return value ? 'Sí' : 'No';
            }
            if (key.includes('price') || key.includes('cost')) {
                return `$${value}`;
            }
            return value;
        },
        
        // Clear specific filter
        clearFilter(key) {
            if (key === 'active' || key === 'in_offer' || key === 'delivery_free') {
                this.filters[key] = false;
            } else {
                this.filters[key] = '';
            }
        },
        
        // Clear all filters
        clearAllFilters() {
            this.filters = {
                name: '',
                min_price: null,
                max_price: null,
                min_cost: null,
                max_cost: null,
                min_stock: null,
                max_stock: null,
                active: false,
                in_offer: false,
                delivery_free: false
            };
            
            // Reset pagination when clearing filters
            this.currentPage = 1;
            this.totalCount = 0;
            this.totalPages = 0;
        },
        
        // Reset form to initial state
        resetForm() {
            this.clearAllFilters();
            this.showResults = false;
            this.productData = null;
            this.searchError = null;
            this.show_error = false;
            
            // Reset pagination
            this.currentPage = 1;
            this.totalCount = 0;
            this.totalPages = 0;
        },

        // Get export filename
        getExportFilename() {
            const timestamp = moment().format('YYYY-MM-DD_HH-mm-ss');
            return `productos-marketplace-${timestamp}.xlsx`;
        },
        
        // Search products
        async searchProducts(event) {
            // Prevenir comportamiento por defecto del formulario
            if (event && event.preventDefault) {
                event.preventDefault();
            }
            
            // Determinar la página: si es un número (desde paginación) usarlo, si no usar 1 (nueva búsqueda)
            const page = (typeof event === 'number') ? event : 1;
            
            this.show_error = false;
            this.isLoading = true;
            this.searchError = null;
            this.showResults = true;
            
            try {
                // Build search filters
                const searchFilters = this.getFilterParams();                
                                
                // Calcular offset para paginación
                const offset = (page - 1) * this.pageSize;
                console.log('Parámetros de paginación - Página:', page, 'Offset:', offset, 'PageSize:', this.pageSize);
                
                // Ejecutar búsqueda paginada y obtener total en paralelo
                const [productsResponse, totalCount] = await Promise.all([
                    MarketplaceItemService.searchAndExport(searchFilters, this.pageSize, offset),
                    MarketplaceItemService.getCount(searchFilters)
                ]);
                
                this.productData = productsResponse;
                this.totalCount = totalCount;
                this.currentPage = page;
                this.totalPages = Math.ceil(totalCount / this.pageSize);
                console.log('Productos totales: ', this.totalPages, this.pageSize, this.totalCount );
                
            } catch (error) {
                console.error('Error searching products:', error);
                this.searchError = error.response?.data?.message || 'Error al buscar productos';
                this.productData = null;
                this.totalCount = 0;
                this.totalPages = 0;
            } finally {
                this.isLoading = false;
            }
        },

        async exportExcel() {
            try {
                const searchFilters = this.getFilterParams();                
                // Para exportar todos los productos, llamamos sin límite (null) y offset 0
                const productsResponse = await MarketplaceItemService.searchAndExport(searchFilters, null, 0);
                return productsResponse;
            } catch (error) {
                console.error('Error exporting products:', error);
                return [];
            }
        },

        getFilterParams() {
            const searchFilters = {};  
            // Add text search
            if (this.filters.name) {
                searchFilters.name = this.filters.name;
            }
            
            // Add price ranges
            if (this.filters.min_price !== null && this.filters.min_price !== '') {
                searchFilters.min_price = parseFloat(this.filters.min_price);
            }
            if (this.filters.max_price !== null && this.filters.max_price !== '') {
                searchFilters.max_price = parseFloat(this.filters.max_price);
            }
            
            // Add cost ranges
            if (this.filters.min_cost !== null && this.filters.min_cost !== '') {
                searchFilters.min_cost = parseFloat(this.filters.min_cost);
            }
            if (this.filters.max_cost !== null && this.filters.max_cost !== '') {
                searchFilters.max_cost = parseFloat(this.filters.max_cost);
            }
            
            // Add stock ranges
            if (this.filters.min_stock !== null && this.filters.min_stock !== '') {
                searchFilters.min_stock = parseInt(this.filters.min_stock);
            }
            if (this.filters.max_stock !== null && this.filters.max_stock !== '') {
                searchFilters.max_stock = parseInt(this.filters.max_stock);
            }
            
            // Add boolean filters
            if (this.filters.active) {
                searchFilters.active = true;
            }
            if (this.filters.in_offer) {
                searchFilters.in_offer = true;
            }
            if (this.filters.delivery_free) {
                searchFilters.delivery_free = true;
            }
             
            return searchFilters;
        },

        // Handle page change
        onPageChanged(newPage) {
            console.log('Cambiando a página:', newPage);
            this.searchProducts(newPage);
        },

        // Handle page size change
        onPageSizeChanged(newSize) {
            this.pageSize = newSize;
            this.currentPage = 1; // Reset to first page when changing page size
            this.searchProducts(1);
        }
    }
}
</script>

<style scoped>
.fade-enter-active, .fade-leave-active {
    transition: opacity 0.3s;
}
.fade-enter, .fade-leave-to {
    opacity: 0;
}

/* Estilos para los badges de filtros activos */
.bg-blue-100 {
    background-color: #dbeafe;
}
.text-blue-800 {
    color: #1e40af;
}
</style>
