<template>
    <div class="crud-marketplace-report">
        <form action="" class="mt-2" @submit.prevent="generateReport">
            <div class="flex-1 flex-col my-3 px-3 py-2 border-double border border-gray-400 rounded-lg">
                <h2 class="inline text-darkGray text-xl ml-4 mb-3">Filtros de búsqueda</h2>
                
                <!-- Report type -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Tipo de reporte
                    </label>
                    <model-select :options="reportTypes"
                        v-model="selectedReportType"
                        placeholder="Seleccione tipo de reporte"
                        required                    
                        class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </model-select>                
                </div>
                <!-- Email -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Email <b v-show="selectedReportType != 'statics'" class="text-red">*</b>
                    </label>
                    <input type="email" 
                        v-model="filters.email"
                        placeholder="correo@ejemplo.com"
                        class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                </div>

                <!-- Order Status -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Estado
                    </label>
                    <model-select :options="orderStatusOptions"
                        v-model="filters.order_status"
                        placeholder="Seleccione estado"
                        required                    
                        class="flex-1 border mt-1 block w-full py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </model-select>                
                </div>

                <!-- Date Range -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Rango de fechas
                    </label>
                    <date-range-picker                    
                        ref="picker"
                        :locale-data="{ firstDay: 1, format: 'yyyy-mm-dd' }"
                        v-model="dateRange"
                        :time-picker="false"
                        :autoApply="true"
                        :ranges="false"
                        @update="updateDateRange"
                        class="dateRangePicker flex-1 border mt-1 block px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                        <template #input="picker">
                            <span class="text-darkGray w-full text-center">
                                {{ picker.startDate | dateFormat('YYYY-MM-DD') }} - {{ picker.endDate | dateFormat('YYYY-MM-DD') }}
                            </span>
                        </template>                
                    </date-range-picker> 
                </div>

                <!-- Reference -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Referencia
                    </label>
                    <input type="text" 
                        v-model="filters.reference"
                        placeholder="MP202510302143500000029"
                        class="flex-1 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                        focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                </div>

                <!-- Amount Range -->
                <div class="flex flex-row items-center my-3 mx-2">
                    <label class="uppercase block text-sm font-medium text-gray-700 mx-2 w-32 ">
                        Rango de monto
                    </label>
                    <div class="flex-1 flex flex-row gap-2">
                        <input type="number" 
                            v-model="filters.min_amount"
                            placeholder="Mínimo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                        <input type="number" 
                            v-model="filters.max_amount"
                            placeholder="Máximo"
                            step="0.01"
                            min="0"
                            class="w-1/2 border mt-1 block py-2 px-3 border-gray-400 bg-white rounded-md shadow-sm 
                            focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    </div>
                </div>

                <!-- Active Filters Summary -->
                <div class="flex flex-wrap gap-2 mt-4 mx-2" v-if="hasActiveFilters">
                    <span class="text-sm text-gray-600 mr-2">Filtros activos:</span>
                    <span v-for="(value, key) in activeFilters" :key="key" 
                        class="inline-flex items-center px-2 py-1 rounded-md text-xs font-medium bg-blue-100 text-blue-800">
                        {{ getFilterLabel(key) }}: {{ formatFilterValue(key, value) }}
                        <button @click="clearFilter(key)" class="ml-1 hover:text-blue-600">
                            <i class="fas fa-times"></i>
                        </button>
                    </span>
                    <button @click="clearAllFilters" class="text-xs text-red-600 hover:text-red-800 ml-2">
                        Limpiar todos
                    </button>
                </div>
            </div>   
                
            <!-- Buttons -->
            <div class="flex flex-1 gap-3 mt-10 gap-y-4">
                <div class="flex flex-col mr-auto">
                    <small class="text-darkGray">Los campos marcados con <b class="text-red">*</b> son obligatorios</small>
                    <transition name="fade">
                        <small class="bg-red text-white px-3 py-2 mt-3 rounded" v-if="show_error">
                            <i class="fa fa-info-circle"></i> {{ error_message }}
                        </small>
                    </transition>
                </div>                                   
                <button type="button" 
                    class="inline-flex border border-gray-400 h-10 bg-red rounded-md font-semibold text-xs text-white uppercase tracking-widest shadow-sm px-4 py-2
                    hover:bg-red-600 focus:outline-none focus:border-red-300 focus:ring focus:ring-red-200 
                    disabled:opacity-25 transition items-center"
                    :disabled="isLoading"
                    @click="resetForm">
                    <i class="fas fa-times mr-2"></i>
                    Cancelar
                </button>         
                <button type="submit" 
                    class="inline-flex border border-transparent h-10 bg-green-600 rounded-md font-semibold text-xs text-white uppercase tracking-widest px-4 py-2 
                    hover:bg-green-500 focus:outline-none focus:border-green-700 focus:ring focus:ring-green-200
                    disabled:opacity-25 transition items-center"
                    :disabled="isLoading">
                    <span class="pr-2" v-if="isLoading">
                        <i class="fa fa-spinner fa-pulse"></i>
                    </span>
                    <i class="fas fa-search mr-2" v-else></i>
                    Generar Reporte
                </button>                              
            </div>
        </form>

        <!-- Results Section con el nuevo componente -->
        <div v-if="showResults" class="mt-8">
            <div class="border-t border-gray-200 my-4"></div>
            
            <!-- Mostrar spinner mientras carga -->
            <div v-if="isLoading" class="flex justify-center items-center py-12">
                <div class="text-center">
                    <i class="fas fa-spinner fa-pulse fa-3x text-blue-500 mb-3"></i>
                    <p class="text-gray-600">Generando reporte...</p>
                </div>
            </div>

            <!-- Mostrar error si ocurre -->
            <div v-else-if="reportError" class="bg-red-50 border-l-4 border-red-400 p-4 mb-4">
                <div class="flex">
                    <div class="flex-shrink-0">
                        <i class="fas fa-exclamation-circle text-red-400"></i>
                    </div>
                    <div class="ml-3">
                        <p class="text-sm text-red-700">{{ reportError }}</p>
                    </div>
                </div>
            </div>

            <!-- Mostrar mensaje si no hay datos -->
            <div v-else-if="reportData && !hasData" class="bg-yellow-50 border-l-4 border-yellow-400 p-4">
                <div class="flex">
                    <div class="flex-shrink-0">
                        <i class="fas fa-exclamation-triangle text-yellow-400"></i>
                    </div>
                    <div class="ml-3">
                        <p class="text-sm text-yellow-700">
                            No se encontraron ventas con los filtros seleccionados.
                        </p>
                    </div>
                </div>
            </div>

            <!-- Mostrar el componente de resultados según el tipo seleccionado -->
            <div v-else-if="reportData && hasData" class="mt-4">
                <!-- Ventas por usuario -->
                <MarketplaceReportSalesUser 
                    v-if="selectedReportType === 'user-sales'"
                    :reportData="reportData"
                    :filters="filters"
                />
                
                <!-- Estadísticas -->
                <MarketplaceReportStatics 
                    v-if="selectedReportType === 'statics'"
                    :reportData="reportData"
                    :filters="filters"
                />
            </div>
        </div>
    </div>
</template>

<script>
import moment from 'moment'
import DateRangePicker from 'vue2-daterange-picker'
import 'vue2-daterange-picker/dist/vue2-daterange-picker.css'
import Swal from 'sweetalert2';

import { ModelSelect } from 'vue-search-select';
import 'vue-search-select/dist/VueSearchSelect.css'
import MarketplaceReportStatics from './partials/MarketplaceReportStatics.vue'
import MarketplaceReportSalesUser from './partials/MarketplaceReportSalesUser.vue'

// Services
import MarketplaceReportService from '@/services/marketplace/marketplace_report.service';

export default {
    name: "CrudMarketplaceReport",
    components: {
        ModelSelect,
        DateRangePicker,
        MarketplaceReportStatics,
        MarketplaceReportSalesUser
    },
    filters: {
        dateFormat(value, format = 'DD MMM YYYY') {
            if (value) {
                return moment(String(value)).format(format);
            }
            return '';
        }
    },
    data() {
        return {
            // Loading states
            isLoading: false,
            show_error: false,
            error_message: 'Faltan campos obligatorios por rellenar',
            
            // Form filters
            filters: {
                email: '',
                order_status: '',
                reference: '',
                min_amount: null,
                max_amount: null
            },
            
            // Date range
            dateRange: {
                startDate: moment().subtract(30, 'days').format('YYYY-MM-DD'),
                endDate: moment().format('YYYY-MM-DD')
            },
            
            // Options for select
            orderStatusOptions: [
                { value: 'created', text: 'Creada' },
                { value: 'pending', text: 'Pendiente' },
                { value: 'paid', text: 'Pagada' },
                { value: 'cancelled', text: 'Cancelada' },
                { value: 'completed', text: 'Completada' }
            ],

            reportTypes: [
                { value: 'user-sales', text: 'Ventas por usuario' },
                { value: 'statics', text: 'Estadísticas' },
            ],
            selectedReportType: 'statics',
            
            // Results
            showResults: false,
            reportData: null
        }
    },
    computed: {
        // Check if form is valid (required fields)
        isFormValid() {
            let isValid = true;
            // isValid = this.filters.email && this.filters.order_status;
            if(this.selectedReportType != 'statics' && this.filters.email == '') {
                isValid = false;
            }
            return isValid;
        },
        
        // Check if there are active filters
        hasActiveFilters() {
            return Object.keys(this.activeFilters).length > 0;
        },
        
        // Get only active filters (with values)
        activeFilters() {
            const active = {};
            Object.entries(this.filters).forEach(([key, value]) => {
                if (value !== null && value !== '' && value !== undefined) {
                    active[key] = value;
                }
            });
            
            // Add date range if different from default
            if (this.dateRange.startDate && this.dateRange.endDate) {
                active.dateRange = `${this.dateRange.startDate} - ${this.dateRange.endDate}`;
            }
            
            return active;
        },

         // Verificar si hay datos para mostrar
        hasData() {
            // console.log('Verificando datos:', this.reportData);
            if (!this.reportData) return false;
            
            // Si es reporte de ventas por usuario (array)
            if (Array.isArray(this.reportData)) {
                return this.reportData.length > 0;
            }
            
            // Si es reporte de estadísticas (objeto)
            if (this.selectedReportType === 'statics') {
                const totalSales = this.reportData?.generalTotal?.totalSales || 0;
                const hasOrders = Object.values(this.reportData?.summaryByStatus || {})
                    .some(status => status.orderCount > 0);
                return totalSales > 0 || hasOrders;
            }
            
            return false;
        },
        
        // Obtener el tipo de reporte seleccionado
        // selectedReportType() {
        //     // Aquí debes vincular esto con el select de tipo de reporte
        //     // Necesitas agregar v-model al select de tipo de reporte
        //     return this.selectedReportTypeValue; // Necesitas crear esta data property
        // },
    },
    methods: {
        // Update date range
        updateDateRange(range) {
            this.dateRange = {
                startDate: moment(range.startDate).format('YYYY-MM-DD'),
                endDate: moment(range.endDate).format('YYYY-MM-DD')
            };
        },
        
        // Get label for filter (for display)
        getFilterLabel(key) {
            const labels = {
                email: 'Email',
                order_status: 'Estado',
                reference: 'Referencia',
                min_amount: 'Monto mín',
                max_amount: 'Monto máx',
                dateRange: 'Rango fechas'
            };
            return labels[key] || key;
        },
        
        // Format filter value for display
        formatFilterValue(key, value) {
            if (key === 'order_status') {
                const option = this.orderStatusOptions.find(opt => opt.value === value);
                return option ? option.text : value;
            }
            if (key === 'min_amount' || key === 'max_amount') {
                return `$${value}`;
            }
            return value;
        },
        
        // Clear specific filter
        clearFilter(key) {
            if (key === 'dateRange') {
                this.dateRange = {
                    startDate: moment().subtract(30, 'days').format('YYYY-MM-DD'),
                    endDate: moment().format('YYYY-MM-DD')
                };
            } else {
                this.filters[key] = '';
            }
        },
        
        // Clear all filters
        clearAllFilters() {
            this.filters = {
                email: '',
                order_status: '',
                reference: '',
                min_amount: null,
                max_amount: null
            };
            this.dateRange = {
                startDate: moment().subtract(30, 'days').format('YYYY-MM-DD'),
                endDate: moment().format('YYYY-MM-DD')
            };
        },
        
        // Reset form to initial state
        resetForm() {
            this.clearAllFilters();
            this.showResults = false;
            this.reportData = null;
            this.show_error = false;
        },
        
        // Generate report (submit form)        
        // async generateReport() {
        //     if (!this.isFormValid) {
        //         this.show_error = true;
        //         this.error_message = 'Email es un campo obligatorio';                
        //         Swal.fire({
        //             icon: 'error',
        //             title: '¡Error!',
        //             text: 'Email es un campo obligatorio',
        //             timer: 2000,
        //             showConfirmButton: false
        //         });
        //         return;
        //     }
            
        //     this.show_error = false;
        //     this.isLoading = true;
        //     this.reportError = null;
            
        //     // Mostrar la sección de resultados inmediatamente
        //     this.showResults = true;
            
        //     try {
        //         // Build request payload
        //         const payload = {
        //             type: this.selectedReportType,
        //             email: this.filters.email,
        //             order_status: this.filters.order_status,
        //             date_ini: this.dateRange.startDate,
        //             date_end: this.dateRange.endDate,
        //         };

        //         // Add optional filters only if they have values
        //         if (this.filters.reference) {
        //             payload.reference = this.filters.reference;
        //         }
                
        //         if (this.filters.min_amount !== null && this.filters.min_amount !== '') {
        //             payload.min_amount = parseFloat(this.filters.min_amount);
        //         }
                
        //         if (this.filters.max_amount !== null && this.filters.max_amount !== '') {
        //             payload.max_amount = parseFloat(this.filters.max_amount);
        //         }
                
        //         // console.log('Generando reporte con filtros:', payload);
                
        //         // TODO: Replace with actual API call
        //         const response = await MarketplaceReportService.searchOrders(payload);
        //         console.log('Respuesta', response.data);
        //         this.reportData = response;
                
        //     } catch (error) {
        //         console.error('Error generating report:', error);
        //         this.reportError = error.response?.data?.message || 'Error al generar el reporte';
        //         this.reportData = null;
        //     } finally {
        //         this.isLoading = false;
        //     }
        // },
        async generateReport() {
            if (!this.isFormValid) {
                this.show_error = true;
                this.error_message = 'Email es un campo obligatorio';                
                Swal.fire({
                    icon: 'error',
                    title: '¡Error!',
                    text: 'Email es un campo obligatorio',
                    timer: 2000,
                    showConfirmButton: false
                });
                return;
            }
            
            this.show_error = false;
            this.isLoading = true;
            this.reportError = null;
            this.showResults = true;
            
            try {
                const payload = {
                    type: this.selectedReportType,
                    email: this.filters.email,
                    order_status: this.filters.order_status,
                    date_ini: this.dateRange.startDate,
                    date_end: this.dateRange.endDate,
                };

                if (this.filters.reference) {
                    payload.reference = this.filters.reference;
                }
                
                if (this.filters.min_amount !== null && this.filters.min_amount !== '') {
                    payload.min_amount = parseFloat(this.filters.min_amount);
                }
                
                if (this.filters.max_amount !== null && this.filters.max_amount !== '') {
                    payload.max_amount = parseFloat(this.filters.max_amount);
                }
                
                // console.log('Generando reporte con filtros:', payload);
                
                const response = await MarketplaceReportService.searchOrders(payload);
                // console.log('Respuesta del servicio:', response);
                
                // Asignar la respuesta directamente
                this.reportData = response;
                
            } catch (error) {
                console.error('Error generating report:', error);
                this.reportError = error.response?.data?.message || 'Error al generar el reporte';
                this.reportData = null;
            } finally {
                this.isLoading = false;
            }
        },

        //  // Handlers para exportación
        // handleExportPDF(data) {
        //     console.log('Exportando a PDF:', data);
        //     // Implementar lógica de exportación a PDF
        //     this.$emit('export-pdf', data);
        // },
        
        // handleExportExcel(data) {
        //     console.log('Exportando a Excel:', data);
        //     // Implementar lógica de exportación a Excel
        //     this.$emit('export-excel', data);
        // }
    }
}
</script>

<style scoped>
.dateRangePicker :deep(.form-control) {
    text-align: left;
    background: transparent !important;
    border: none !important;    
    width: 100%;
}

.fade-enter-active, .fade-leave-active {
    transition: opacity 0.3s;
}
.fade-enter, .fade-leave-to {
    opacity: 0;
}

/* Estilos para los badges de filtros activos */
.bg-blue-100 {
    background-color: #dbeafe;
}
.text-blue-800 {
    color: #1e40af;
}
</style>