<template>
    <div class="marketplace-report-sales-user">
        <!-- Header con totales generales -->
        <div class="flex items-center gap-3 mb-6">
            <h2 class="text-2xl font-bold text-gray-800">👥 Ventas por Usuario</h2>
            <div class="ml-auto flex gap-2">
                <SalesPDFReport 
                    :reportData="reportData" 
                    :filters="filters"
                    :filename="`reporte-ventas-${reference}-${currentDate}.pdf`"
                />
                <SalesExcelReport 
                    :reportData="reportData" 
                    :filters="filters"
                    :filename="`reporte-ventas-${reference}-${currentDate}.xlsx`"
                />
            </div>
        </div>

        <!-- Tarjetas de resumen por estado -->
        <div class="grid grid-cols-1 md:grid-cols-5 gap-3 mb-6">
            <div v-for="(data, status) in summaryByStatus" :key="status" class="rounded-lg p-3 text-white shadow-md" :class="getStatusCardClass(status)">
                <div class="text-xs opacity-90 uppercase">{{ getStatusLabel(status) }}</div>
                <div class="text-lg font-bold">{{ data.count }}</div>
                <div class="text-xs opacity-75">${{ formatCurrency(data.total) }}</div>
            </div>
        </div>

        <!-- Tabs de navegación -->
        <div class="border-b border-gray-200 mb-4">
            <nav class="flex -mb-px">
                <button @click="activeTab = 'orders'" :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition', activeTab === 'orders' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-list mr-2"></i>Órdenes ({{ totalOrders }})
                </button>
                <button @click="activeTab = 'products'" :class="['mr-8 py-2 px-1 border-b-2 font-medium text-sm transition', activeTab === 'products' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300']">
                    <i class="fas fa-box mr-2"></i>Productos ({{ totalUniqueProducts }})
                </button>
            </nav>
        </div>

        <!-- Tab: Listado de Órdenes -->
        <div v-if="activeTab === 'orders'" class="bg-white rounded-lg shadow overflow-hidden">
            <div class="overflow-x-auto">
                <table class="min-w-full divide-y divide-gray-200">
                    <thead class="bg-gray-50">
                        <tr>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Referencia</th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Fecha</th>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Estado</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Items</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Total Costos</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Total</th>
                        </tr>
                    </thead>
                    <tbody class="bg-white divide-y divide-gray-200">
                        <tr v-for="order in sortedOrders" :key="order.id" class="hover:bg-gray-50 cursor-pointer transition" @click="toggleOrderDetails(order.id)">
                            <td class="px-4 py-3 text-sm font-mono">{{ order.reference }}</td>
                            <td class="px-4 py-3 text-sm">{{ formatDate(order.order_date) }}</td>
                            <td class="px-4 py-3 text-sm">
                                <span class="px-2 py-1 rounded-full text-xs font-medium" :class="getStatusBadgeClass(order.status)">
                                    {{ getStatusLabel(order.status) }}
                                </span>
                            </td>
                            <td class="px-4 py-3 text-sm text-right">{{ order.items && order.items.length ? order.items.length : 0 }}</td>
                            <td class="px-4 py-3 text-sm font-semibold text-right">${{ formatCurrency(order.amount_cost) }}</td>
                            <td class="px-4 py-3 text-sm font-semibold text-right">${{ formatCurrency(order.amount) }}</td>
                        </tr>
                        <tr v-if="sortedOrders.length">
                            <td colspan="1" class="px-4 text-left font-semibold">
                                <small>Cantidad: {{ totalOrders }}</small>
                            </td>
                            <td colspan="4" class="px-4 text-right font-semibold">
                                <small>Subtotal: ${{ totalAmountOrders }}</small>
                            </td>
                        </tr>
                        <tr v-if="!sortedOrders.length">
                            <td colspan="5" class="px-4 py-8 text-center text-gray-500">
                                No hay órdenes para mostrar
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Tab: Resumen de Productos -->
        <div v-if="activeTab === 'products'" class="bg-white rounded-lg shadow overflow-hidden">
            <div class="p-4 border-b border-gray-200 bg-gray-50">
                <div class="flex items-center justify-between">
                    <h3 class="font-semibold text-gray-700">Resumen de Productos Vendidos</h3>
                    <div class="relative w-64">
                        <input type="text" v-model="productSearch" placeholder="Buscar producto..." class="w-full border rounded-lg pl-8 pr-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <i class="fas fa-search absolute left-3 top-3 text-gray-400 text-xs"></i>
                    </div>
                </div>
            </div>
            
            <div class="overflow-x-auto">
                <table class="min-w-full divide-y divide-gray-200">
                    <thead class="bg-gray-50">
                        <tr>
                            <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Producto</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Cantidad</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Costos Totales</th>
                            <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Total</th>
                        </tr>
                    </thead>
                    <tbody class="bg-white divide-y divide-gray-200">
                        <tr v-for="(product, name) in filteredProductsSummary" :key="name" class="hover:bg-gray-50 transition">
                            <td class="px-4 py-3 text-sm text-gray-900">{{ name }}</td>
                            <td class="px-4 py-3 text-sm text-right font-medium">{{ product.quantity }}</td>
                            <td class="px-4 py-3 text-sm text-right font-medium">{{ formatCurrency(product.cost) }}</td>
                            <td class="px-4 py-3 text-sm text-right font-semibold text-green-600">${{ formatCurrency(product.total) }}</td>
                        </tr>
                        <tr v-if="!Object.keys(filteredProductsSummary).length">
                            <td colspan="3" class="px-4 py-8 text-center text-gray-500">
                                No hay productos para mostrar
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    </div>
</template>

<script>
import moment from 'moment'
import SalesPDFReport from '@/components/marketplace/SalesPDFReport.vue';
import SalesExcelReport from '@/components/marketplace/SalesExcelReport.vue';

export default {
    name: 'MarketplaceReportSalesUser',
    props: {
        reportData: {
            type: Array,
            default: () => []
        },
        filters: {
            type: Object,
            default: () => ({})
        }
    },
    components: {
        SalesPDFReport,
        SalesExcelReport
    },
    data() {
        return {
            expandedOrder: null,
            activeTab: 'orders',
            productSearch: ''
        }
    },
    computed: {
        reference() { return this.reportData[0].reference; },
        currentDate() {
            const date = new Date();
            return date.toISOString().split('T')[0];
        },
        userData(){
            const user = this.reportData[0].marketplace_user;
            // const name = user.
            return ''
        },
        totalOrders() {
             return this.reportData ? this.reportData.length : 0
        },
        totalAmountOrders() {
             let total = 0;
             const orders = this.reportData || []
             orders.forEach(order => total += parseFloat(order.amount || 0))
             return total.toFixed(2);
        },
        summaryByStatus() {
            const summary = {
            created: { count: 0, total: 0 },
            pending: { count: 0, total: 0 },
            paid: { count: 0, total: 0 },
            cancelled: { count: 0, total: 0 },
            completed: { count: 0, total: 0 }
            }

            const orders = this.reportData || []

            orders.forEach(order => {
            if (summary[order.status]) {
                summary[order.status].count += 1
                summary[order.status].total += parseFloat(order.amount || 0)
            }
            })

            return summary
        },
        sortedOrders() {
            return [...(this.reportData || [])].sort((a, b) => new Date(b.order_date) - new Date(a.order_date))
        },
        productSummary() {
            const summary = {}
            const orders = this.reportData || []

            orders.forEach(order => {
                const items = order.items || []

                items.forEach(item => {
                    const quantity = parseFloat(item.quantity || 0)
                    const cost = parseFloat(item.cost || 0) * quantity
                    const total = parseFloat(item.final_price || 0) * quantity

                    if (!summary[item.name]) {
                        summary[item.name] = {
                            quantity: 0,
                            cost: 0,
                            total: 0
                        }
                    }

                    summary[item.name].quantity += quantity                                        
                    summary[item.name].cost += cost
                    summary[item.name].total += total
                })
            })

            return summary
        },
        totalUniqueProducts() {
            if(!this.productSummary) return 0;
            return Object.keys(this.productSummary).length
        },
        filteredProductsSummary() {
            if (!this.productSearch) return this.productSummary
            const searchLower = this.productSearch.toLowerCase()
            return Object.fromEntries(
                Object.entries(this.productSummary).filter(([name]) => name.toLowerCase().includes(searchLower))
            )
        }
    },
    methods: {
        toggleOrderDetails(orderId) {
            this.expandedOrder = this.expandedOrder === orderId ? null : orderId
        },
        formatCurrency(value) {
            if (!value && value !== 0) return '0.00'
            return parseFloat(value).toFixed(2)
        },
        formatDate(date) {
            if (!date) return ''
            return moment(date).format('DD/MM/YYYY')
        },
        getStatusLabel(status) {
            const labels = { created: 'Creada', pending: 'Pendiente', paid: 'Pagada', cancelled: 'Cancelada', completed: 'Completada' }
            return labels[status] || status
        },
        getStatusBadgeClass(status) {
            const classes = {
                created: 'bg-gray-100 text-gray-800',
                pending: 'bg-yellow-100 text-yellow-800',
                paid: 'bg-green-100 text-green-800',
                cancelled: 'bg-red-100 text-red-800',
                completed: 'bg-blue-100 text-blue-800'
            }
            return classes[status] || 'bg-gray-100 text-gray-800'
        },
        getStatusCardClass(status) {
            const classes = {
                created: 'bg-gradient-to-br from-gray-500 to-gray-600',
                pending: 'bg-gradient-to-br from-yellow-500 to-yellow-600',
                paid: 'bg-gradient-to-br from-green-500 to-green-600',
                cancelled: 'bg-gradient-to-br from-red-500 to-red-600',
                completed: 'bg-gradient-to-br from-blue-500 to-blue-600'
            }
            return classes[status] || 'bg-gradient-to-br from-gray-400 to-gray-500'
        }
    }
}
</script>

<style scoped>
.cursor-pointer { cursor: pointer; }
</style>