<!-- components/marketplace/SalesExcelReport.vue -->
<template>
  <button @click="exportExcel" class="excel-export-btn" :disabled="loading">
    <i class="fa fa-spinner fa-pulse mr-2" v-if="loading"></i>
    <i class="fa fa-file-excel mr-2" v-else></i>
    {{ loading ? 'Generando Excel...' : 'Excel' }}
  </button>
</template>

<script>
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

export default {
  name: "SalesExcelReport",
  props: {
    reportData: {
      type: Array, // Array de órdenes
      required: true
    },
    filters: {
      type: Object,
      default: () => ({})
    },
    filename: {
      type: String,
      default: "reporte-ventas-usuario.xlsx"
    }
  },
  data() {
    return {
      loading: false
    };
  },
  computed: {
    userInfo() {
      if (!this.reportData || !this.reportData.length) return null;
      return this.reportData[0]?.marketplace_user || null;
    },
    summaryByStatus() {
      const summary = {
        created: { count: 0, total: 0 },
        pending: { count: 0, total: 0 },
        paid: { count: 0, total: 0 },
        cancelled: { count: 0, total: 0 },
        completed: { count: 0, total: 0 }
      };

      this.reportData.forEach(order => {
        if (summary[order.status]) {
          summary[order.status].count += 1;
          summary[order.status].total += parseFloat(order.amount || 0);
        }
      });

      return summary;
    },
    productSummary() {
      const summary = {};

      this.reportData.forEach(order => {
        const items = order.items || [];
        items.forEach(item => {
          const quantity = parseFloat(item.quantity || 0);
          const tcost = parseFloat(item.cost || 0) * quantity;
          const total = parseFloat(item.price_unit || 0) * quantity;

          if (!summary[item.name]) {
            summary[item.name] = {
              quantity: 0,
              totalCost: 0,
              total: 0,
              cost: parseFloat(item.cost || 0),
              price: parseFloat(item.price_unit || 0)
            };
          }

          summary[item.name].quantity += quantity;
          summary[item.name].totalCost += tcost;
          summary[item.name].total += total;
        });
      });

      return summary;
    },
    totalOrders() {
      return this.reportData?.length || 0;
    },
    totalSales() {
      return this.reportData.reduce((sum, order) => sum + parseFloat(order.amount || 0), 0);
    }
  },
  methods: {
    async exportExcel() {
      try {
        this.loading = true;
        
        // Crear workbook
        const wb = XLSX.utils.book_new();
        
        // Hoja de resumen del usuario
        const userSheet = this.createUserSummarySheet();
        XLSX.utils.book_append_sheet(wb, userSheet, "Resumen Usuario");
        
        // Hoja de órdenes
        const ordersSheet = this.createOrdersSheet();
        XLSX.utils.book_append_sheet(wb, ordersSheet, "Órdenes");
        
        // Hoja de productos
        const productsSheet = this.createProductsSheet();
        XLSX.utils.book_append_sheet(wb, productsSheet, "Productos");
        
        // Hoja de resumen por estado
        const statusSheet = this.createStatusSheet();
        XLSX.utils.book_append_sheet(wb, statusSheet, "Resumen por Estado");
        
        // Hoja de filtros
        const filtersSheet = this.createFiltersSheet();
        XLSX.utils.book_append_sheet(wb, filtersSheet, "Filtros Aplicados");
        
        // Generar archivo
        const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const data = new Blob([excelBuffer], { type: 'application/octet-stream' });
        saveAs(data, this.filename);
        
      } catch (error) {
        console.error("Error exportando Excel:", error);
        alert("Error al generar el archivo Excel.");
      } finally {
        this.loading = false;
      }
    },

    createUserSummarySheet() {
      const user = this.reportData[0].marketplace_user;
      
      const data = [
        ['REPORTE DE VENTAS POR USUARIO'],
        [],
        ['Información del Usuario', ''],
        ['Nombre', user.first_name ? `${user.first_name} ${user.last_name}` : 'N/A'],
        ['Email', user?.email || 'N/A'],
        ['Teléfono', user?.phone || 'N/A'],
        [],
        ['Resumen General', ''],
        ['Total Órdenes', this.totalOrders],
        ['Total Ventas', `$${this.totalSales.toFixed(2)}`],
        ['Total Productos Vendidos', Object.keys(this.productSummary).length],
        [],
        ['Fecha de generación', new Date().toLocaleString('es-ES')]
      ];
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 25 },
        { wch: 30 }
      ];
      
      return ws;
    },

    createOrdersSheet() {
      const data = [
        ['LISTADO DE ÓRDENES'],
        [],
        ['Referencia', 'Ext Referencia', 'Fecha', 'Estado', 'Items', 'Subtotal Costo', 'Subtotal', 'Envío', 'Total', 'Productos']
      ];
      
      this.reportData.forEach(order => {
        const subtotal = order.items?.reduce((sum, item) => sum + (item.price_unit * item.quantity), 0) || 0;
        const subtotalCost = order.items?.reduce((sum, item) => sum + (item.cost * item.quantity), 0) || 0;      
        // const amountCost = order.amount_cost || 0;
        const itemsList = (order.items || [])
          .map(item => `${item.name} (x${item.quantity})`)
          .join(', ');
        
        data.push([
          order.reference,
          order.ext_reference || '',
          this.formatDate(order.order_date),
          this.getStatusLabel(order.status),
          order.items?.length || 0,
          `$${parseFloat(subtotalCost || 0).toFixed(2)}`,
          `$${parseFloat(subtotal || 0).toFixed(2)}`,
          `$${parseFloat(order.delivery || 0).toFixed(2)}`,
          // `$${parseFloat(amountCost || 0).toFixed(2)}`,
          `$${parseFloat(order.amount || 0).toFixed(2)}`,
          itemsList
        ]);
      });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 20 }, // Referencia
        { wch: 20 }, // Ext Referencia
        { wch: 12 }, // Fecha
        { wch: 12 }, // Estado
        { wch: 8 },  // Items
        { wch: 12 }, // Subtotal Costo
        { wch: 12 }, // Subtotal
        { wch: 10 }, // Envío
        // { wch: 12 }, // Total Costo
        { wch: 12 }, // Total
        { wch: 50 }  // Productos
      ];
      
      return ws;
    },

    createProductsSheet() {
      const data = [
        ['RESUMEN DE PRODUCTOS'],
        [],
        ['Producto', 'Cantidad Vendida', 'Precio Unitario', 'Costo Unitario', 'Costo Total', 'Total', '% del Total']
      ];
      
      const totalSales = this.totalSales;
      
      Object.entries(this.productSummary)
        .sort((a, b) => b[1].total - a[1].total)
        .forEach(([name, info]) => {
          const percentage = totalSales > 0 ? ((info.total / totalSales) * 100).toFixed(1) : 0;
          
          data.push([
            name,
            info.quantity,
            `$${info.price.toFixed(2)}`,
            `$${info.cost.toFixed(2)}`,
            `$${info.totalCost.toFixed(2)}`,
            `$${info.total.toFixed(2)}`,
            `${percentage}%`
          ]);
        });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 45 }, // Producto
        { wch: 15 }, // Cantidad
        { wch: 15 }, // Precio Unitario
        { wch: 15 }, // Costo
        { wch: 15 }, // Total Costo
        { wch: 15 }, // Total
        { wch: 10 }  // %
      ];
      
      return ws;
    },

    createStatusSheet() {
      const data = [
        ['RESUMEN POR ESTADO'],
        [],
        ['Estado', 'Cantidad Órdenes', 'Total Ventas']
      ];
      
      Object.entries(this.summaryByStatus).forEach(([status, info]) => {
        if (info.count > 0 || info.total > 0) {
          data.push([
            this.getStatusLabel(status),
            info.count,
            `$${info.total.toFixed(2)}`
          ]);
        }
      });
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 20 },
        { wch: 15 },
        { wch: 15 }
      ];
      
      return ws;
    },

    createFiltersSheet() {
      const data = [
        ['FILTROS APLICADOS'],
        [],
        ['Filtro', 'Valor']
      ];
      
      if (this.filters.email) data.push(['Email', this.filters.email]);
      if (this.filters.order_status) {
        data.push(['Estado', this.getStatusLabel(this.filters.order_status)]);
      }
      if (this.filters.date_ini && this.filters.date_end) {
        data.push(['Rango de fechas', `${this.filters.date_ini} al ${this.filters.date_end}`]);
      }
      if (this.filters.reference) data.push(['Referencia', this.filters.reference]);
      if (this.filters.min_amount) data.push(['Monto mínimo', `$${this.filters.min_amount}`]);
      if (this.filters.max_amount) data.push(['Monto máximo', `$${this.filters.max_amount}`]);
      
      data.push([]);
      data.push(['Fecha de exportación', new Date().toLocaleString('es-ES')]);
      
      const ws = XLSX.utils.aoa_to_sheet(data);
      
      ws['!cols'] = [
        { wch: 25 },
        { wch: 40 }
      ];
      
      return ws;
    },

    formatDate(date) {
      if (!date) return '';
      const d = new Date(date);
      return d.toLocaleDateString('es-ES');
    },

    getStatusLabel(status) {
      const labels = {
        created: 'Creada',
        pending: 'Pendiente',
        paid: 'Pagada',
        cancelled: 'Cancelada',
        completed: 'Completada'
      };
      return labels[status] || status;
    }
  }
};
</script>

<style scoped>
.excel-export-btn {
  padding: 5px 10px;
  background-color: #016526;
  color: white;
  border: none;
  cursor: pointer;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
}
.excel-export-btn:hover:not(:disabled) {
  background-color: #008531;
  transform: translateY(-1px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.excel-export-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
</style>