<template>
   <div>
      <div class="info-message flex item-center p-4 rounded-xl" :class="{'hidden': haveData}">
         <i class="fas fa-exclamation-circle"></i>
         <span>No existe ninguna información en la base de datos. <br> Inserte los datos accediendo al formulario a traves del boton + en la esquina superior derecha.</span>
      </div>
      <div class="flex justify-end items-center" v-if="haveData">
         <button 
         class="inline-flex border border-transparent bg-red rounded-md font-semibold text-xs uppercase text-white px-4 py-2 mr-auto" 
         @click="deleteRows"
         v-if="isAdmin && !showDelete"><i class="fa fa-trash mx-1"></i></button>
         <label for="filter">Filtro: </label>
         <input id="filterValue" 
         class="form-control border-b my-4 px-3 no-underline
         focus:outline-none"
         v-model="filterValue"/>
      </div>  
      <div class="overflow-x-auto">
         <v-table 
            v-if="columns.length > 0"
            :data="rows"
            :filters="filters"
            :currentPage.sync="currentPage"
            :pageSize="25"
            @totalPagesChanged="totalPages = $event">
            <thead slot="head" class="uppercase text-white">
               <th v-if="(isAdmin)"><input type="checkbox" v-model="all" @click="clearSelection"></th>
               <th v-for="(col, index) in columns" :key="index" 
                   @click="handleHeaderClick(col, index)"
                   :class="{ 'cursor-pointer hover:bg-gray-700': isBooleanColumn(col), 'sortable': isBooleanColumn(col) }">
                   {{ col }}
                   <span v-if="isBooleanColumn(col)" class="ml-2 text-xs">
                     <i v-if="getSortState(col) === 'true'" class="fas fa-sort-amount-down text-green-400"></i>
                     <i v-else-if="getSortState(col) === 'false'" class="fas fa-sort-amount-up text-red-400"></i>
                     <i v-else class="fas fa-sort text-gray-400"></i>
                   </span>
               </th>
               <th v-if="actions.show">actions</th>
            </thead>
            <tbody slot="body" slot-scope="{displayData}">            
               <tr v-for="(row, i) in displayData" :key="row.id" :class="{'bg-row': (i%2 > 0)}">
                  <td v-if="isAdmin"><input type="checkbox" :value="row.id" :checked="all" @click="getitemToDelete(row.id, $event)"></td>
                  <td v-for="(col, index) in columns" :key="index">   
                     <span class="text-green" v-if="(typeof row[col] == 'boolean' && row[col])"><i class="fas fa-check"></i></span>
                     <span class="text-red" v-if="(typeof row[col] == 'boolean' && !row[col])"><i class="fas fa-minus-circle"></i></span>
                     <div 
                        v-if="(typeof row[col] != 'boolean')" 
                        v-html="row[col]" 
                        :contenteditable="editableColumns"                                                
                        @blur="onContentEditableBlur($event, row.id, col)"
                     ></div>
                  </td>
                  <td v-if="actions.show">
                     <button type="button" class="ui small button" 
                     @click="edit(row)"
                     v-if="actions.edit">
                        <i class="fa fa-edit text-indigo-700 hover:opacity-50 m-2"></i>
                     </button>    
                     <button type="button" class="ui small button" 
                     @click="deleteRow(row.id)"
                     v-if="actions.delete && !showDelete">
                        <i class="fa fa-trash text-red-600 hover:opacity-50 m-2"></i>
                     </button>     
                  </td>               
               </tr>
            </tbody>
         </v-table>
      </div>          
      <smart-pagination v-if="totalPages > 0"
        :currentPage.sync="currentPage"
        :totalPages="totalPages"
        :maxPageLinks="5"
      />
   </div>
</template>

<script>
//https://tochoromero.github.io/vuejs-smart-table/the-basics/#import
import authService from "@/services/user/auth.service"

export default { 
   props: {
      rows: [],    
      actions: {
         default: {
            show: true,
            edit: true,
            delete: true
         }
      },
      deleteCols: [],
      editableColumns: false
   },
   name: 'AdminTable',
   data() {
      return {
         info: `No existe ninguna información en la base de datos. <br> Inserte los datos accediendo al formulario a traves del boton + en la esquina superior derecha.`,
         isAdmin: false,
         columns: [],
         tableInfo: [],         
         filters: {},
         all: false,
         items_id: [],
         currentPage: 1,
         totalPages: 0,
         activeFilter: 'alias', // Filtro activo por defecto
         // Para controlar debounce en las actualizaciones
         editTimer: null,
         // Estados de ordenamiento para columnas booleanas
         booleanSortStates: {}
      }
   },   
   created() {
      this.isAdmin = authService.validateRole(['ROLE_Admin', 'ROLE_Comercial'])
      this.initTable()

      // Inicializa filtros dinámicamente
      this.initializeFilters();
      // upd actions controlls
      this.actions.show = (this.actions.show) ? this.actions.show : true
      this.actions.edit = (this.actions.edit) ? this.actions.edit : false
      this.actions.delete = (this.actions.delete) ? this.actions.delete : false
      
   },
   computed: {
      haveData() {         
         if (this.columns.length <= 0){
            this.totalPages = 0
            return false
         }
         return true
      },
      showDelete(){
         return this.$route.params.CrudKey === 'booking';
      },
      filterValue: {
         get() {
            // Obtiene el valor del primer filtro disponible
            const filterKey = this.getPrimaryFilterKey();
            return filterKey ? this.filters[filterKey]?.value || '' : '';
         },
         set(newValue) {
            // Asigna el valor al filtro primario
            const filterKey = this.getPrimaryFilterKey();
            if (filterKey && this.filters[filterKey]) {
               this.filters[filterKey].value = newValue;
            }
         }
      },
      // Para usar en v-table
      activeFilters() {
         const filterKey = this.getPrimaryFilterKey();
         return filterKey ? this.filters[filterKey] : { value: '', keys: [] };
      },
      // Detecta si una columna contiene datos booleanos
      booleanColumns() {
         if (!this.rows || this.rows.length === 0) return [];
         
         return this.columns.filter(col => {
            return this.rows.some(row => typeof row[col] === 'boolean');
         });
      }
   },  
   watch: {
      rows() {
         this.initTable()         
      },
      columns: {
         handler(newColumns) {
            this.initializeFilters();
         },
         deep: true
      }
   }, 
   methods: {
      initTable() {            
         this.columns = []           
         if (this.rows != undefined){
            if(this.rows.length > 0) {
               const cols = Object.keys(this.rows[0])
               if (cols[0] == 'id') cols.shift()
               // shift other cols            
               cols.map(c => {
                  if(this.deleteCols.findIndex(e => e == c) < 0){
                     this.columns.push(c)
                  }
               })
            }
         }
      },    
      edit(rowData) {
         this.$emit('editData', rowData)  
      },
      clearSelection() {
         if (!this.all) {
            this.rows.map(e => {
               this.items_id.push(e.id)
            })
         } else this.items_id = []
      },
      getitemToDelete(item_id, e) {
         if(e.target.checked) {
            if(this.items_id.findIndex(i => i == item_id) == -1) {
               this.items_id.push(item_id)
            }
         } else {
            const del = this.items_id
            this.items_id = []
            del.map(i => {
               if(i != item_id)
                  this.items_id.push(i)
            })
         }
      },      
      deleteRow(rowData) {
         this.items_id = [rowData]    
         this.deleteRows()         
      },
      deleteRows() {    
         if(confirm("Desea realmente eliminar estos elementos?")) 
            this.$emit('deleteData', this.items_id)
      },   
      
      // NUEVOS MÉTODOS PARA CONTENTEDITABLE
      
      /**
       * Maneja el evento blur (cuando el elemento pierde el foco)
       * Útil para emitir solo cuando el usuario termina de editar
       */
      onContentEditableBlur(event, rowId, columnName) {
         const newValue = event.target.innerText || '';
         
         // Solo emitir si el valor realmente cambió
         const oldValue = this.getOriginalValue(rowId, columnName);
         console.log(newValue, oldValue);
         if(newValue == oldValue) return;
         this.$emit('cell-updated', {
            id: rowId,
            column: columnName,
            value: newValue,
            oldValue: oldValue
         });
         this.setOriginalValue(rowId, columnName, newValue);
      },
      
      /**
       * Obtiene el valor original de una celda
       */
      getOriginalValue(rowId, columnName) {
         const row = this.rows.find(r => r.id === rowId);
         return row ? row[columnName] : '';
      },
      setOriginalValue(rowId, columnName, value) {
         const row = this.rows.find(r => r.id === rowId);
         if (row) {
            row[columnName] = value;
         }
      },
      
      // Filter methods
      // Determina la columna principal para filtrar
      getPrimaryFilterKey() {
         const priorityOrder = ['alias', 'reference', 'name', 'email', 'title'];
        
        // Busca en orden de prioridad
        for (const key of priorityOrder) {
            if (this.columns.includes(key) && this.filters[key]) {
               return key;
            }
        }
        
        // Si no encuentra ninguna prioritaria, usa la primera columna
        if (this.columns.length > 0) {
            return this.columns[0];
        }
        
        return null;
      },      
      // Inicializa los filtros dinámicamente
      initializeFilters() {
         // Crea un objeto vacío primero
         const newFilters = {};
         
         // Para cada columna, crea un filtro
         this.columns.forEach(column => {
            // Define las keys para buscar (puede ser la columna misma o un array)
            const keys = [column];
            
            // Puedes personalizar según el nombre de la columna
            if (column === 'fullName') {
               keys.push('firstName', 'lastName');
            } else if (column === 'address') {
               keys.push('street', 'city', 'zipCode');
            }
            
            newFilters[column] = {
               value: '',
               keys: keys
            };
         });
         
         // Actualiza filters manteniendo los valores existentes si es posible
         Object.keys(newFilters).forEach(key => {
            if (this.filters[key] && this.filters[key].value !== undefined) {
               newFilters[key].value = this.filters[key].value;
            }
         });
         
         this.filters = newFilters;
      },
      
      // Métodos para ordenamiento de columnas booleanas
      isBooleanColumn(columnName) {
         return this.booleanColumns.includes(columnName);
      },
      
      getSortState(columnName) {
         return this.booleanSortStates[columnName] || 'all';
      },
      
      handleHeaderClick(columnName, columnIndex) {
         if (!this.isBooleanColumn(columnName)) return;
         
         // Toggle entre estados: all -> true -> false -> all
         const currentState = this.getSortState(columnName);
         let newState;
         
         switch (currentState) {
            case 'all':
               newState = 'true';
               break;
            case 'true':
               newState = 'false';
               break;
            case 'false':
               newState = 'all';
               break;
            default:
               newState = 'all';
         }
         
         // Actualizar estado
         this.$set(this.booleanSortStates, columnName, newState);
         
         // Emitir evento al componente padre
         this.$emit('boolean-sort', {
            column: columnName,
            state: newState,
            columnIndex: columnIndex
         });
      }
         
   }
}
</script>

<style scoped>
/* Estilos opcionales para mejorar la experiencia de edición */
[contenteditable="true"] {
   cursor: text;
   min-height: 1.5em;
   padding: 2px 4px;
   border-radius: 4px;
   transition: background-color 0.2s;
}

[contenteditable="true"]:hover {
   background-color: rgba(0, 0, 0, 0.02);
}

[contenteditable="true"]:focus {
   outline: 2px solid #4a90e2;
   background-color: white;
}
</style>